<?php
namespace App\Service\HelloAsso;
use App\Entity\HelloAssoPayment;use App\Entity\Participant;use App\Entity\Subscription;use App\Enum\HelloAssoPaymentMatchStatusEnum as MS;use App\Enum\RegistrationStatusEnum;use App\Repository\HelloAssoPaymentRepository;use App\Repository\ParticipantRepository;use App\Repository\SubscriptionRepository;use Doctrine\DBAL\Exception\UniqueConstraintViolationException;use Doctrine\ORM\EntityManagerInterface;use Psr\Log\LoggerInterface;
final class HelloAssoPaymentProcessor{public function __construct(private EntityManagerInterface $em,private HelloAssoPaymentRepository $payments,private ParticipantRepository $participants,private SubscriptionRepository $subscriptions,private ParticipantIdentityMatcher $identity,private string $org,private string $formType,private string $formSlug,private LoggerInterface $logger){}public function process(HelloAssoWebhookPayload $p):HelloAssoPayment{return $this->em->wrapInTransaction(fn()=> $this->doProcess($p));}public function reconcile(HelloAssoPayment $payment):HelloAssoPayment{$p=new HelloAssoWebhookPayload('Payment',$payment->getPaymentId()??'', $payment->getPaymentState(),$payment->getOrderId(),$payment->getOrganizationSlug(),$payment->getFormType(),$payment->getFormSlug(),$payment->getTierId(),$payment->getAmount(),$payment->getAmount(),$payment->getReceiptUrl(),$payment->getPayerEmail(),$payment->getPayerFirstname(),$payment->getPayerLastname(),[],[],$payment->getPayloadHash()??'');return $this->em->wrapInTransaction(fn()=> $this->evaluate($payment,$p));}private function doProcess(HelloAssoWebhookPayload $p):HelloAssoPayment{$payment=$this->payments->findOneBy(['paymentId'=>$p->paymentId])??(new HelloAssoPayment())->setPaymentId($p->paymentId);$same=$payment->getPayloadHash()===$p->payloadHash;$this->fill($payment,$p);if(!$p->isExpected($this->org,$this->formType,$this->formSlug)){$payment->setMatchStatus(MS::IGNORED)->setMismatchReason('Notification ignored: unexpected HelloAsso form.');$this->em->persist($payment);$this->em->flush();return $payment;}if($same&&$payment->getMatchStatus()===MS::MATCHED){return $payment;}try{$this->em->persist($payment);$this->evaluate($payment,$p);$this->em->flush();}catch(UniqueConstraintViolationException $exception){$this->em->clear();$existing=$this->payments->findOneBy(['paymentId'=>$p->paymentId]);if($existing instanceof HelloAssoPayment)return $existing;throw $exception;}return $payment;}private function evaluate(HelloAssoPayment $payment,HelloAssoWebhookPayload $p):HelloAssoPayment{$payment->setUpdatedAt(new \DateTimeImmutable());if($this->isRefunded($p->paymentState)){$payment->setMatchStatus(MS::REFUNDED)->setProcessedAt(new \DateTimeImmutable());$part=$payment->getParticipant();if($part instanceof Participant&&$part->getRegistrationStatus()===RegistrationStatusEnum::PAID)$part->setRegistrationStatus(RegistrationStatusEnum::REFUNDED);return $payment;}if(!$this->isSuccessful($p->paymentState)){$payment->setMatchStatus(MS::PENDING)->setMismatchReason('Payment state is not accepted for validation.');return $payment;}$participant=$payment->getParticipant()??$this->findParticipant($p);if(!$participant){return $payment->setMatchStatus(MS::UNMATCHED_PARTICIPANT)->setMismatchReason('No participant found from internal reference or payer email.');}$payment->setParticipant($participant);if(!$this->emailMatches($participant,$p->payerEmail)&&!$this->hasExactReference($participant,$p))return $payment->setMatchStatus(MS::IDENTITY_MISMATCH)->setMismatchReason('Payer email does not match participant email.');if(!$this->identity->matches($participant,$p->payerFirstname,$p->payerLastname))return $payment->setMatchStatus(MS::IDENTITY_MISMATCH)->setMismatchReason('Payer firstname/lastname does not match participant identity.');$subscription=$this->findActiveSubscription($p->tierId);if(!$subscription)return $payment->setMatchStatus(MS::UNKNOWN_TIER)->setMismatchReason('No active subscription matches the HelloAsso tierId.');$payment->setSubscription($subscription);if($p->tierAmount!==null&&$subscription->getPrice()!==$p->tierAmount)return $payment->setMatchStatus(MS::AMOUNT_MISMATCH)->setMismatchReason('HelloAsso item amount does not match subscription price.');if($participant->getRegistrationStatus()===RegistrationStatusEnum::PAID){$other=$this->payments->createQueryBuilder('h')->andWhere('h.participant = :p')->andWhere('h.matchStatus = :s')->andWhere('h.paymentId != :pid')->setParameter('p',$participant)->setParameter('s',MS::MATCHED)->setParameter('pid',$payment->getPaymentId())->setMaxResults(1)->getQuery()->getOneOrNullResult();if($other instanceof HelloAssoPayment)return $payment->setMatchStatus(MS::PAYMENT_CONFLICT)->setMismatchReason('Participant is already paid with another HelloAsso payment.');}else{$participant->setRegistrationStatus(RegistrationStatusEnum::PAID)->setSubscription($subscription);if($participant->getPaidAt()===null)$participant->setPaidAt(new \DateTimeImmutable());}$payment->setMatchStatus(MS::MATCHED)->setMismatchReason(null)->setProcessedAt(new \DateTimeImmutable());return $payment;}private function fill(HelloAssoPayment $h,HelloAssoWebhookPayload $p):void{$h->setOrderId($p->orderId)->setOrganizationSlug($p->organizationSlug)->setFormType($p->formType)->setFormSlug($p->formSlug)->setTierId($p->tierId)->setPayerEmail($p->payerEmail)->setPayerFirstname($p->payerFirstname)->setPayerLastname($p->payerLastname)->setPaymentState($p->paymentState)->setAmount($p->amount)->setReceiptUrl($p->receiptUrl)->setPayloadHash($p->payloadHash);}private function findParticipant(HelloAssoWebhookPayload $p):?Participant{foreach($p->metadata as $v){if(is_scalar($v)&&($x=$this->participants->findOneBy(['internalReference'=>(string)$v])))return $x;}foreach($p->customFieldValues as $v){if(($x=$this->participants->findOneBy(['internalReference'=>$v])))return $x;}foreach($p->customFieldValues as $v){if(filter_var($v,FILTER_VALIDATE_EMAIL)&&($x=$this->participants->findOneByEmail($v)))return $x;}return $p->payerEmail?$this->participants->findOneByEmail($p->payerEmail):null;}private function hasExactReference(Participant $p,HelloAssoWebhookPayload $payload):bool{return in_array($p->getInternalReference(),array_map('strval',array_merge(array_values($payload->metadata),$payload->customFieldValues)),true);}private function emailMatches(Participant $p,?string $email):bool{return $email!==null&&mb_strtolower(trim($p->getEmail()??''))===mb_strtolower(trim($email));}private function findActiveSubscription(?string $tier):?Subscription{if(!$tier)return null;$s=$this->subscriptions->findOneByHelloAssoTierId($tier);return $s instanceof Subscription&&$s->isActive()?$s:null;}private function isSuccessful(?string $s):bool{return in_array(strtolower((string)$s),['authorized','processed','succeeded','paid'],true);}private function isRefunded(?string $s):bool{return in_array(strtolower((string)$s),['refunded','refund','reimbursed'],true);}}
